fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // By assumption, the two arrays have equal length.
    assert_eq!(arr1.len(), arr2.len());

    // Pre‐allocate the result vector to avoid repeated reallocations.
    let mut result = Vec::with_capacity(arr1.len());

    // Compute element‐wise remainder.
    for (&a, &b) in arr1.iter().zip(arr2.iter()) {
        // By assumption, b != 0, so `a % b` is well‐defined.
        result.push(a % b);
    }

    result
}

